def walk(path):
    out = []
    for name in repo.list(path):
        full = path + "/" + name if path != "." else name
        if name.endswith("/"):
            out.extend(walk(full.rstrip("/")))
        else:
            out.append(full)
    return out

files = walk("src")
changed = []
for f in files:
    content = repo.read(f)
    if "V1_TAG" in content:
        repo.write(f, content.replace("V1_TAG", "V2_TAG"))
        changed.append(f)

remaining = repo.search("V1_TAG", glob = "src/**")
result({"changed": changed, "remaining_src_hits": len(remaining), "diff": repo.diff()})
